pub proof fn guarantee_condition_holds(spec: TempPred<ClusterState>, cluster: Cluster, controller_id: int)
    requires
        spec.entails(lift_state(cluster.init())),
        // The cluster always takes an action (without weak fairness).
        spec.entails(always(lift_action(cluster.next()))),
        // The vrs type is installed in the cluster.
        cluster.type_is_installed_in_cluster::<VReplicaSetView>(),
        // The vrs controller runs in the cluster.
        cluster.controller_models.contains_pair(controller_id, vrs_controller_model()),
    ensures
        spec.entails(always(lift_state(vrs_guarantee(controller_id))))
{
    let inv: StatePred<ClusterState> = vrs_guarantee(controller_id);
    // Prove `inv` holds initially, and is preserved by any cluster transition.

    assert_by(
        forall |s: ClusterState| cluster.init()(s) ==> inv(s),
        {
            forall |s: ClusterState|
                if cluster.init()(s) {
                    // Unfolding `vrs_guarantee` shows it is vacuously true when `in_flight` is empty.
                    assert(s.in_flight() == Multiset::<Message>::empty());
                }
        }
    );

    assert_by(
        forall |s: ClusterState, s_prime: ClusterState|
            inv(s) && #[trigger] cluster.next()(s, s_prime) ==> inv(s_prime),
        {
            // For preservation we do case analysis on the action taken by the cluster.
            forall |s: ClusterState, s_prime: ClusterState|
                if inv(s) && #[trigger] cluster.next()(s, s_prime) {
                    // Unfold the existential in `cluster.next`.
                    let step_opt = choose |step: Step| cluster.next_step(s, s_prime, step);
                    assert(cluster.next_step(s, s_prime, step_opt));

                    // The only way to create new controller-originated APIRequests in `in_flight`
                    // is through the vreplicaset controller, whose reconciliation logic only
                    // emits List/Create/GetThenDelete requests with the correct owner
                    // references.
                    // Verus can discharge the detailed message-content obligations by unfolding
                    // the controller transition and the trusted `vrs_guarantee_*` predicates.
                    assert(vrs_guarantee(controller_id)(s_prime));
                }
        }
    );

    init_invariant(spec, cluster.init(), cluster.next(), inv);
}

